import{_ as a,c as e,o as t,af as s}from"./chunks/framework.BKeRpnBD.js";const f=JSON.parse('{"title":"43、【夬】 乾下兌上","description":"子夏易傳 - 43、【夬】 乾下兌上","frontmatter":{"title":"43、【夬】 乾下兌上","description":"子夏易傳 - 43、【夬】 乾下兌上"},"headers":[],"relativePath":"classics/zixia/045.md","filePath":"classics/zixia/045.md"}'),i={name:"classics/zixia/045.md"};function r(_,p,c,o,n,l){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="_43、【夬】-乾下兌上" tabindex="-1">43、【夬】 乾下兌上 <a class="header-anchor" href="#_43、【夬】-乾下兌上" aria-label="Permalink to “43、【夬】 乾下兌上”">​</a></h1><p>卦辭：夬，揚於王庭，孚號有厲，告自邑，不利即戎，利有攸往。</p><p>彖曰：夬，決也，剛決柔也。健而説，決而和。揚於王庭，柔乘五剛也。孚號有厲，其危乃光也。告自邑不利，即戎所尚，乃窮也。利有攸往，剛長乃終也。</p><p>子夏：陽長終位而陰微也。君子在位，小人在野，健制而能悅之，不隱情也。剛決而能和之，不任力而剛不過中也。故顯於王庭而民得治也。夫用九即吉於無首也，剛長即兇於用壯也。道之窮則不富矣，其危矣哉。信有危而思患，呻號終無刑，乃保其光也。告自邑，揚而令之從也。不利即戎，肆剛騁力，道途斯變。利有攸往，柔道外而剛治遂終也。</p><p>象曰：澤上於天，夬。君子以施祿及下，居徳則忌。</p><p>子夏：澤上於天，上澤以及下也。上以明法，決治致其平也。君子以施祿及下，惠其澤也。選徳以居其位，取則以上為禁，盡已而不敢上越也。</p><p>初九，壯於前，趾往不勝，為咎。</p><p>象曰：不勝而往，咎也。</p><p>子夏：陽處體初，志在乎前，趾將行以，求勝也。壯之用斯窮之矣，下之微也，何可勝哉。知其不可以往之，自為咎也。</p><p>九二，惕號莫夜，有戎勿恤。</p><p>象曰：有戎勿恤，得中道也。</p><p>子夏：以剛而退，守於柔，知其危而懼，呻號戎於昧矣，可為戎，無敵也。何所憂乎，得其中道，吉也。</p><p>九三，壯於頄，有兇，君子夬夬，獨行遇雨若濡，有慍，無咎。</p><p>象曰：君子夬夬，終無咎也。</p><p>子夏：當位上應，往而為壯，內得其心，外形於色，壯見於頄也。行而與邪兇之道也。夫君子治已，豈係於私哉。雖獨行，遇應而潤於我，而反恕其邪志，匪其失亦又何咎。</p><p>九四，臀無膚，其行次且，牽羊悔亡。聞言不信。</p><p>象曰：其行次且，位不當也。聞言不信，聦不明也。</p><p>子夏：志進決柔而逼於上，坐不能安，行不能正，剛而不當其位也。羊者，觗突不迴之物，比之用壯，焉能自牽。繫其志，不縱其壯，則悔亡也。是語也，聽之而不能明，昧為其道者也。</p><p>九五，莧陸夬夬，中行無咎。</p><p>象曰：中行無咎，中未光也。</p><p>子夏：上無位之尊也。決，其決至易也。莧陸之柔，脃也。以至尊之徳，務至微之物，則缺於與能矣。夬而得中，無咎而已豈足以為光哉。</p><p>上六，無號，終有兇。</p><p>象曰：無號之兇，終不可長也。</p><p>子夏：剛長而一柔尚存，亡無日矣。雖號之無及已也。</p>',24)])])}const m=a(i,[["render",r]]);export{f as __pageData,m as default};
